// Quran Firm Plant - Where an ayah sits in the mushaf
// Page and juz lookups from the static index in ayah-index.js (generated by
// scripts/build-ayah-index.mjs), so nothing has to be downloaded to place a verse.

import { AYAH_PAGES, V1_PAGES, JUZ_STARTS } from './ayah-index.js';

// The Page Map's edition: 'v2' (QCF layouts, the default) or 'v1' (Quran.com's layout,
// which puts a few ayahs on a neighbouring page)
export function getMushafEdition() {
  try {
    return localStorage.getItem('mushaf-edition') === 'v1' ? 'v1' : 'v2';
  } catch {
    return 'v2';
  }
}

// The page (1-604) surah:ayah starts on in that edition, or null if there is no such ayah
export function pageOfAyah(surah, ayah, edition = getMushafEdition()) {
  const page = AYAH_PAGES[surah - 1]?.[ayah - 1];
  if (page == null) return null;
  return (edition === 'v1' && V1_PAGES[`${surah}:${ayah}`]) || page;
}

// The juz (1-30) of surah:ayah, or null if there is no such ayah
export function juzOfAyah(surah, ayah) {
  if (AYAH_PAGES[surah - 1]?.[ayah - 1] == null) return null;
  let juz = 1;
  while (juz < JUZ_STARTS.length) {
    const [s, a] = JUZ_STARTS[juz]; // where the next juz starts
    if (surah < s || (surah === s && ayah < a)) break;
    juz++;
  }
  return juz;
}
